import json
import os
import tempfile
import unittest

import app as nenios

class AppTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.NamedTemporaryFile(delete=False)
        self.tmp.close()
        nenios.DATA_FILE = nenios.Path(self.tmp.name)
        if nenios.DATA_FILE.exists():
            nenios.DATA_FILE.unlink()
        self.client = nenios.app.test_client()

    def tearDown(self):
        if nenios.DATA_FILE.exists():
            nenios.DATA_FILE.unlink()

    def test_family_child_classroom_invoice_payment_flow(self):
        r = self.client.post('/classrooms', json={'name': 'Toddlers', 'capacity': 2})
        self.assertEqual(r.status_code, 201)
        classroom_id = r.get_json()['id']

        r = self.client.post('/families', json={'name': 'Smith', 'contacts': [{'name': 'A', 'phone': '111'}], 'billing_email': 'a@example.com'})
        self.assertEqual(r.status_code, 201)
        family_id = r.get_json()['id']

        r = self.client.post('/children', json={'family_id': family_id, 'name': 'Jamie', 'classroom_id': classroom_id, 'immunization_status': 'current'})
        self.assertEqual(r.status_code, 201)
        child_id = r.get_json()['id']

        r = self.client.get(f'/children/{child_id}')
        self.assertEqual(r.status_code, 200)
        self.assertEqual(r.get_json()['classroom']['name'], 'Toddlers')

        r = self.client.post('/invoices', json={'family_id': family_id, 'amount': 100, 'items': ['tuition']})
        invoice = r.get_json()
        self.assertEqual(invoice['balance'], 100.0)

        r = self.client.post('/payments', json={'invoice_id': invoice['id'], 'amount': 40, 'payer': 'authorized guardian'})
        self.assertEqual(r.status_code, 201)
        r = self.client.get('/invoices')
        self.assertEqual(r.get_json()[0]['balance'], 60.0)

    def test_classroom_capacity_blocking(self):
        self.client.post('/classrooms', json={'name': 'Infants', 'capacity': 1})
        family = self.client.post('/families', json={'name': 'Jones'}).get_json()
        self.client.post('/children', json={'family_id': family['id'], 'name': 'First', 'classroom_id': 1})
        r = self.client.post('/children', json={'family_id': family['id'], 'name': 'Second', 'classroom_id': 1})
        self.assertEqual(r.status_code, 409)

    def test_immunization_update(self):
        family = self.client.post('/families', json={'name': 'Brown'}).get_json()
        child = self.client.post('/children', json={'family_id': family['id'], 'name': 'Kid'}).get_json()
        r = self.client.get(f'/children/{child["id"]}/immunization')
        self.assertEqual(r.get_json()['status'], 'missing')
        r = self.client.post(f'/children/{child["id"]}/immunization', json={'status': 'current'})
        self.assertTrue(r.get_json()['compliant'])

if __name__ == '__main__':
    unittest.main()
